// Fungsi ini tidak pernah return nilai apapun
// karena selalu throw sebelum sempat return
function lemparError(pesan: string): never {
  throw new Error(pesan);
  // Baris setelah throw tidak akan pernah dieksekusi
}

// Berbeda dengan void — void artinya return undefined
// never artinya TIDAK PERNAH return sama sekali
function cetakLog(pesan: string): void {
  console.log(pesan);
  // Fungsi ini return undefined secara implisit
}

type Status = 'aktif' | 'nonaktif' | 'suspended';

function handleStatus(status: Status): string {
  switch (status) {
    case 'aktif':
      return 'User aktif';
    case 'nonaktif':
      return 'User tidak aktif';
    case 'suspended':
      return 'User disuspend';
    default:
      // Kalau semua case sudah ditangani, TypeScript tahu
      // bahwa 'status' di sini bertipe 'never'
      // Ini adalah safety net — kalau ada Status baru ditambahkan
      // tapi switch-nya belum diupdate, baris ini akan error
      const _exhaustiveCheck: never = status;
      return _exhaustiveCheck;
  }
}

